      </div>
      <button class="btn btn-secondary btn-sm" id="reindex-btn" onclick="window.__app.reindexProject()">⟳ Reindex</button>
      <span style="font-size:11px;color:var(--text-muted)">Semantic powered by Ollama qwen3</span>
    </div>
